import './App.css';
import { useEffect } from 'react';

function keyHandler(){
  useEffect(()=>{
    const script = document.createElement('script');
    script.src = `https://trello.com/1/client.js?key=${process.env.MY_API_KEY}`;
    document.head.appendChild(script);
  });
}

function App() {

  return (
    <div className="App">
      <h1>Welcome</h1>
      <button onClick={keyHandler}>
        點我使用該死的授權
      </button>
    </div>
  );
}

export default App;
